#!/usr/bin/env bash
# ──────────────────────────────────────────────────────────────────────────────
#  TabBridge — MCP connector  (pure bash, no other dependencies)
#  Connector @@CONNECTOR_ID@@ · profile "@@PROFILE_NAME@@"
#  Generated by the extension (v@@VERSION@@) on @@ISSUED_ISO@@ · initial validity until @@EXPIRES_ISO@@
#  Validity (lifetime, deactivation, extension) is managed in the plugin's Web MCP page:
#  this script asks the plugin at start and is refused when expired or deactivated.
#
#  Usage
#    bash tabbridge-connector.sh            → registers itself with Chrome and prints the
#                                                         mcpServers config to paste into any AI agent
#    bash tabbridge-connector.sh --stdio    → what the agent runs (MCP over stdio)
#    bash tabbridge-connector.sh --uninstall
#
#  How it works: the agent talks MCP to this script over stdio. The script hands
#  every message to the TabBridge inside Chrome (via Chrome Native
#  Messaging — Chrome launches this same file as the "host") and relays the
#  answer back. The extension is the MCP server; this file only moves bytes.
#
#  Only the tools enabled in the profile above are listed or callable. The
#  plugin's Web MCP page lists this connector and can deactivate, extend or
#  delete it at any time. Keep this file private: it carries the connector's token.
# ──────────────────────────────────────────────────────────────────────────────
set -u
export LC_ALL=C
umask 077   # everything this script creates (spool, manifests) is private to the user

TOKEN='@@TOKEN@@'
EXT_ID='@@EXT_ID@@'
HOST_NAME='@@HOST_NAME@@'
SERVER_KEY='@@SERVER_KEY@@'
CONNECTOR_ID='@@CONNECTOR_ID@@'
PROFILE_NAME='@@PROFILE_NAME@@'
ISSUED_AT=@@ISSUED_AT@@
EXPIRES_AT=@@EXPIRES_AT@@
VERSION='@@VERSION@@'

HOME_DIR="${TABBRIDGE_HOME:-${HOME:?}/.tabbridge}"
SPOOL="${HOME_DIR:?}/spool"
INSTALL_DIR="${HOME_DIR:?}/bin"
SELF="$(cd "$(dirname "$0")" && pwd)/$(basename "$0")"
# The copy Chrome and the agent actually run. ~/Downloads, ~/Desktop and ~/Documents are
# protected by macOS privacy (TCC): an MCP host app or Chrome spawning bash there gets
# "Operation not permitted". So setup installs the script into ~/.tabbridge/bin and
# registers/prints THAT path. The downloaded copy can be deleted afterwards.
TARGET="$INSTALL_DIR/$(basename "$SELF")"
REQUEST_TIMEOUT_S="${TABBRIDGE_TIMEOUT_S:-90}"
case "$REQUEST_TIMEOUT_S" in ''|*[!0-9]*) REQUEST_TIMEOUT_S=90 ;; esac   # digits only — never arithmetic-expand env input

fmt_date() { date -r "$1" 2>/dev/null || date -d "@$1" 2>/dev/null || echo "epoch $1"; }
log() { printf '%s\n' "$*" >&2; }

# ─── Lifetime ────────────────────────────────────────────────────────────────
# Not enforced here. EXPIRES_AT above is only the validity at download time; the
# plugin decides (hello handshake + every call) and the user can extend or
# re-activate this connector from the Web MCP page without a new download.

# ─── Native-host registration (idempotent) ───────────────────────────────────
json_escape() { printf '%s' "$1" | sed 's/\\/\\\\/g; s/"/\\"/g'; }

browser_dirs() {
  case "$(uname -s)" in
    Darwin)
      b="$HOME/Library/Application Support"
      printf '%s\n' "$b/Google/Chrome" "$b/Google/Chrome Beta" "$b/Google/Chrome Canary" "$b/Chromium" \
        "$b/BraveSoftware/Brave-Browser" "$b/Microsoft Edge" "$b/Vivaldi" "$b/Arc/User Data" ;;
    *)
      b="${XDG_CONFIG_HOME:-$HOME/.config}"
      printf '%s\n' "$b/google-chrome" "$b/google-chrome-beta" "$b/google-chrome-unstable" "$b/chromium" \
        "$b/BraveSoftware/Brave-Browser" "$b/microsoft-edge" "$b/vivaldi" ;;
  esac
}

INSTALLED=""
install_self() {
  mkdir -p "$INSTALL_DIR" && chmod 700 "$HOME_DIR" "$INSTALL_DIR" 2>/dev/null
  if [ "$SELF" != "$TARGET" ]; then
    cp "$SELF" "$TARGET.tmp" && mv -f "$TARGET.tmp" "$TARGET"
  fi
  chmod 700 "$TARGET" 2>/dev/null || true
  # Note: the macOS quarantine flag on downloaded files is left in place on purpose. It does not
  # block a shell script from being executed (directly, via bash, or spawned by another app),
  # and stripping it is a behaviour endpoint-security tools rightly flag.
  return 0
}

install_host() {
  install_self
  mkdir -p "$SPOOL" && chmod 700 "$HOME_DIR" "$SPOOL" 2>/dev/null
  manifest="{
  \"name\": \"$HOST_NAME\",
  \"description\": \"TabBridge MCP connector\",
  \"path\": \"$(json_escape "$TARGET")\",
  \"type\": \"stdio\",
  \"allowed_origins\": [ \"chrome-extension://$EXT_ID/\" ]
}"
  first=""
  while IFS= read -r dir; do
    [ -n "$first" ] || first="$dir"
    [ -d "$dir" ] || continue
    mkdir -p "$dir/NativeMessagingHosts" && printf '%s\n' "$manifest" > "$dir/NativeMessagingHosts/$HOST_NAME.json" \
      && INSTALLED="$INSTALLED
    $dir/NativeMessagingHosts/$HOST_NAME.json"
  done <<DIRS
$(browser_dirs)
DIRS
  if [ -z "$INSTALLED" ] && [ -n "$first" ]; then
    mkdir -p "$first/NativeMessagingHosts" && printf '%s\n' "$manifest" > "$first/NativeMessagingHosts/$HOST_NAME.json"
    INSTALLED="
    $first/NativeMessagingHosts/$HOST_NAME.json   (no browser profile found yet — Chrome will pick it up on first launch)"
  fi
}

# True when some browser already has a manifest pointing at an existing script.
host_registered() {
  while IFS= read -r dir; do
    f="$dir/NativeMessagingHosts/$HOST_NAME.json"
    [ -f "$f" ] || continue
    registered=$(sed -n 's/.*"path": *"\([^"]*\)".*/\1/p' "$f" | head -1)
    [ -n "$registered" ] && [ -f "$registered" ] || continue
    # Registered host must be the same template version (an older template may speak a different protocol).
    r_ver=$(sed -n "s/^VERSION='\(.*\)'$/\1/p" "$registered" | head -1)
    [ "$r_ver" = "$VERSION" ] && return 0
  done <<DIRS
$(browser_dirs)
DIRS
  return 1
}

uninstall_host() {
  n=0
  while IFS= read -r dir; do
    f="${dir:?}/NativeMessagingHosts/${HOST_NAME:?}.json"
    [ -f "$f" ] && rm -f "$f" && n=$((n+1))
  done <<DIRS
$(browser_dirs)
DIRS
  rm -rf "${SPOOL:?}"
  rm -f "${INSTALL_DIR:?}/$(basename "$SELF")"
  log "Removed $n native-messaging manifest(s), the spool directory and the installed copy."
}

# ─── Native messaging framing (4-byte little-endian length + JSON) ───────────
write_frame() {
  len=${#1}
  printf "$(printf '\\%03o' $((len & 255)) $(((len >> 8) & 255)) $(((len >> 16) & 255)) $(((len >> 24) & 255)))"
  printf '%s' "$1"
}

# Reads exactly $1 bytes from stdin to stdout. `dd bs=N count=1` never reads
# past N, unlike `head -c`, which can slurp the next frame when Chrome writes
# header and body in one go. Short reads on pipes are handled by looping.
read_exact() {
  n=$1
  while [ "$n" -gt 0 ]; do
    chunk=$(dd bs="$n" count=1 2>/dev/null; printf x)
    chunk=${chunk%x}
    [ -n "$chunk" ] || return 1
    printf '%s' "$chunk"
    n=$((n - ${#chunk}))
  done
}

# Reads one frame from stdin into FRAME. Returns 1 on EOF / short read.
read_frame() {
  hdr=$(dd bs=1 count=4 2>/dev/null | od -An -tu1) || return 1
  set -- $hdr
  [ $# -eq 4 ] || return 1
  len=$(( $1 + $2 * 256 + $3 * 65536 + $4 * 16777216 ))
  FRAME=$(read_exact "$len"; printf x) || return 1
  FRAME=${FRAME%x}
  [ ${#FRAME} -eq "$len" ]
}

# ─── Role: native host (Chrome launches this; $1 = chrome-extension://…/) ────
run_native_host() {
  # Chrome passes the calling extension's origin; serve only the extension this script was made for.
  if [ "${1:-}" != "chrome-extension://$EXT_ID/" ]; then
    log "✗ Refusing native-messaging caller ${1:-<none>} (expected chrome-extension://$EXT_ID/)."
    exit 6
  fi
  mkdir -p "$SPOOL" && chmod 700 "$HOME_DIR" "$SPOOL" 2>/dev/null
  # A backgrounded subshell gets /dev/null as stdin in non-interactive bash, so
  # hand it Chrome's pipe explicitly via fd 3.
  exec 3<&0
  # Reader: extension → spool/<id>.res  (whole envelope; the relay strips the prefix)
  (
    while read_frame; do
      [ "${FRAME:0:7}" = '{"id":"' ] || continue
      id=${FRAME:7:32}
      case "$id" in *[!0-9a-f]*) continue ;; esac
      printf '%s' "$FRAME" > "${SPOOL:?}/${id:?}.tmp" && mv -f "${SPOOL:?}/${id:?}.tmp" "${SPOOL:?}/${id:?}.res"
    done
    kill $$ 2>/dev/null   # Chrome closed the port
  ) <&3 &
  reader=$!
  trap 'kill "$reader" 2>/dev/null; exit 0' TERM INT EXIT

  # Writer: spool/<id>.req → extension, plus a keep-alive ping every ~20 s.
  tick=0
  while kill -0 "$reader" 2>/dev/null; do
    for f in "${SPOOL:?}"/*.req; do
      [ -e "$f" ] || continue
      content=$(cat "$f"); rm -f "${f:?}"
      [ -n "$content" ] && write_frame "$content"
    done
    tick=$((tick + 1))
    if [ "$tick" -ge 200 ]; then
      tick=0
      write_frame '{"type":"ping"}'
      # Replies nobody collected (relay timed out / died) must not linger on disk,
      # and requests from a relay that died must not be replayed later.
      find "${SPOOL:?}" -maxdepth 1 \( -name '*.res' -o -name '*.req' -o -name '*.tmp' \) -mmin +2 -delete 2>/dev/null || true
    fi
    sleep 0.1
  done
}

# ─── Role: stdio relay (the agent launches this) ─────────────────────────────
new_id() { od -An -N16 -tx1 /dev/urandom | tr -d ' \n'; }

# JSON-RPC error for a request we could not deliver. Notifications (no id) stay silent.
emit_error() {
  re='"id"[[:space:]]*:[[:space:]]*("[^"]*"|[0-9]+)'
  if [[ $1 =~ $re ]]; then
    printf '{"jsonrpc":"2.0","id":%s,"error":{"code":-32000,"message":"%s"}}\n' "${BASH_REMATCH[1]}" "$2"
  fi
}

# Asks the plugin whether this connector may be served (not deactivated / expired / unknown).
# Exits 5 when refused. When the plugin is unreachable we continue — later calls surface the error.
hello_check() {
  id=$(new_id)
  PENDING_REQ="${SPOOL:?}/${id:?}.req"
  prefix='{"id":"'"$id"'","line":'
  printf '%s' '{"hello":true,"ts":'"$(date +%s)"',"id":"'"$id"'","token":"'"$TOKEN"'"}' > "${SPOOL:?}/${id:?}.tmp" && mv -f "${SPOOL:?}/${id:?}.tmp" "$PENDING_REQ"
  waited=0
  while [ ! -e "$SPOOL/$id.res" ]; do
    sleep 0.05
    waited=$((waited + 1))
    if [ "$waited" -eq 60 ]; then
      log "… waiting for the TabBridge in Chrome (is 'Expose tools via Web MCP' switched on?)"
    fi
    if [ "$waited" -ge $((REQUEST_TIMEOUT_S * 20)) ]; then
      rm -f "${SPOOL:?}/${id:?}.req"; PENDING_REQ=""
      log "⚠ Could not reach the plugin to verify connector $CONNECTOR_ID; continuing — tool calls will fail until it is reachable."
      return 0
    fi
  done
  res=$(cat "$SPOOL/$id.res"); rm -f "${SPOOL:?}/${id:?}.res"
  PENDING_REQ=""
  body=${res:${#prefix}}
  case "$body" in
    '{"ok":true'*) return 0 ;;
  esac
  message=$(printf '%s' "$body" | sed -n 's/.*"message":"\([^"]*\)".*/\1/p')
  log "✗ Sorry — connector $CONNECTOR_ID (profile \"$PROFILE_NAME\") cannot be used."
  log "  ${message:-The plugin refused this connector.}"
  exit 5
}

run_relay() {
  # Register as native host only when no working registration exists; the
  # explicit no-arg run always (re)registers. Keeps old scripts from hijacking.
  host_registered || install_host
  # If the agent kills us mid-request (hello included), take the pending request
  # with us so the next host start cannot replay it.
  PENDING_REQ=""
  relay_cleanup() { [ -n "$PENDING_REQ" ] && rm -f "$PENDING_REQ"; return 0; }
  trap relay_cleanup EXIT                       # keeps the real exit code (5 on refusal)
  trap 'relay_cleanup; exit 143' TERM
  trap 'relay_cleanup; exit 130' INT
  trap 'relay_cleanup; exit 129' HUP
  hello_check
  while IFS= read -r line || [ -n "$line" ]; do
    [ -z "$line" ] && continue
    id=$(new_id)
    PENDING_REQ="${SPOOL:?}/${id:?}.req"
    prefix='{"id":"'"$id"'","line":'
    # The agent's raw line goes FIRST; id/token/ts come last so a line that tries to
    # break out of the "line" slot and inject its own "token"/"id" keys loses
    # (JSON parsers keep the last duplicate key).
    printf '%s' '{"line":'"$line"',"ts":'"$(date +%s)"',"id":"'"$id"'","token":"'"$TOKEN"'"}' > "${SPOOL:?}/${id:?}.tmp" && mv -f "${SPOOL:?}/${id:?}.tmp" "$PENDING_REQ"

    waited=0; warned=0
    while [ ! -e "$SPOOL/$id.res" ]; do
      sleep 0.05
      waited=$((waited + 1))
      if [ "$waited" -eq 60 ] && [ "$warned" -eq 0 ]; then
        warned=1
        log "… waiting for the TabBridge in Chrome (is 'Expose tools via Web MCP' switched on?)"
      fi
      if [ "$waited" -ge $((REQUEST_TIMEOUT_S * 20)) ]; then
        rm -f "${SPOOL:?}/${id:?}.req"; PENDING_REQ=""
        emit_error "$line" "TabBridge did not answer within ${REQUEST_TIMEOUT_S}s. In Chrome open the plugin's Settings → Web MCP: switch on 'Expose tools via Web MCP' (or click Retry now)."
        continue 2
      fi
    done

    res=$(cat "$SPOOL/$id.res"); rm -f "${SPOOL:?}/${id:?}.res"
    PENDING_REQ=""
    if [ "${res:0:${#prefix}}" = "$prefix" ]; then
      body=${res:${#prefix}}
      body=${body%\}}
      [ "$body" != "null" ] && printf '%s\n' "$body"
    else
      emit_error "$line" "Malformed reply from the extension."
    fi
  done
}

# ─── Role: setup + print config (default) ────────────────────────────────────
print_config() {
  self_json=$(json_escape "$TARGET")
  cat <<JSON
{
  "mcpServers": {
    "$SERVER_KEY": {
      "command": "bash",
      "args": [
        "$self_json",
        "--stdio"
      ],
      "env": {}
    }
  }
}
JSON
  log ""
  log "✓ Connector $CONNECTOR_ID (profile \"$PROFILE_NAME\") installed to $TARGET"
  log "  and registered with Chrome:$INSTALLED"
  [ "$SELF" != "$TARGET" ] && log "  (You can delete the downloaded copy at $SELF — agents run the installed one. ~/Downloads is blocked for other apps by macOS privacy settings.)"
  log ""
  log "↑ Paste the block above into your AI agent's MCP config (Claude Desktop, Cursor, .mcp.json, …)."
  log "  Claude Code:  claude mcp add $SERVER_KEY -- bash \"$TARGET\" --stdio"
  log "  Then make sure 'Expose tools via Web MCP' is ON in the plugin's settings page — it shows Connected within a minute."
  log "  Only the tools enabled in profile \"$PROFILE_NAME\" are exposed. Deactivate, extend or delete this connector any time from that page."
  log "  Initially valid until $(fmt_date "$EXPIRES_AT") — extend it in the plugin when needed; no new download required."
}

case "${1:-}" in
  --stdio)              run_relay ;;
  chrome-extension://*) run_native_host "$1" ;;
  --uninstall)          uninstall_host ;;
  *)                    install_host; print_config ;;
esac
